"""Tests for scripts/ci_cargo_cache.py (the CI Cargo cache helper)."""

import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import ci_cargo_cache

LOCKFILE = """\
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "opus"
version = "0.4.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"

[[package]]
name = "pumice"
version = "{version}"
dependencies = [
 "opus",
]
"""

WORKSPACE = {"pumice", "pumice-transcription"}
WS_HASH = "0123456789abcdef"
WS_TEST_HASH = "1111111111111111"
WS_BUILD_HASH = "2222222222222222"
DEP_HASH = "fedcba9876543210"
SYS_HASH = "3333333333333333"


def touch(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(b"x")
    return path


def make_profile(profile: Path) -> None:
    """A profile directory with workspace units, an external crate whose
    name is also a workspace test target (`opus`) and a CMake-built -sys
    dependency."""
    for name in (
        f".fingerprint/pumice-transcription-{WS_HASH}/lib-pumice_transcription",
        f".fingerprint/pumice-transcription-{WS_TEST_HASH}/test-integration-test-opus",
        f".fingerprint/opus-{DEP_HASH}/lib-opus",
        f".fingerprint/transcribe-cpp-sys-{SYS_HASH}/run-build-script",
        f"build/pumice-transcription-{WS_BUILD_HASH}/build-script-build",
        f"build/transcribe-cpp-sys-{SYS_HASH}/output",
        f"build/transcribe-cpp-sys-{SYS_HASH}/out/lib/libtranscribe.so",
        f"build/transcribe-cpp-sys-{SYS_HASH}/out/build/CMakeCache.txt",
        f"build/transcribe-cpp-sys-{SYS_HASH}/out/build/ggml/ggml.c.o",
        f"deps/libpumice_transcription-{WS_HASH}.rlib",
        f"deps/pumice_transcription-{WS_HASH}.d",
        f"deps/opus-{WS_TEST_HASH}",
        f"deps/opus-{WS_TEST_HASH}.d",
        f"deps/libopus-{DEP_HASH}.rlib",
        f"deps/opus-{DEP_HASH}.d",
        "deps/transcribe.dll",
        "incremental/pumice-abc/s-1/query-cache.bin",
        "pumice-transcribe",
        "pumice-transcribe.d",
        ".cargo-lock",
    ):
        touch(profile / name)


def listing(root: Path) -> set:
    return {
        path.relative_to(root).as_posix()
        for path in root.rglob("*")
        if path.is_file()
    }


class LockfileTests(unittest.TestCase):
    def test_workspace_versions_do_not_change_the_dependencies(self):
        with tempfile.TemporaryDirectory() as tmp:
            lock = Path(tmp) / "Cargo.lock"
            lock.write_text(LOCKFILE.format(version="0.3.0"))
            first = ci_cargo_cache.lockfile_dependencies(lock)
            lock.write_text(LOCKFILE.format(version="0.4.0"))
            self.assertEqual(ci_cargo_cache.lockfile_dependencies(lock), first)
            self.assertIn('name = "opus"', first)
            self.assertNotIn('name = "pumice"', first)

    def test_crlf_checkout_reads_the_same(self):
        with tempfile.TemporaryDirectory() as tmp:
            lf = Path(tmp) / "lf.lock"
            crlf = Path(tmp) / "crlf.lock"
            text = LOCKFILE.format(version="0.3.0")
            lf.write_bytes(text.encode())
            crlf.write_bytes(text.replace("\n", "\r\n").encode())
            self.assertEqual(
                ci_cargo_cache.lockfile_dependencies(crlf),
                ci_cargo_cache.lockfile_dependencies(lf),
            )


class KeyTests(unittest.TestCase):
    ENV = {"ImageOS": "ubuntu24", "RUNNER_OS": "Linux", "RUNNER_ARCH": "X64"}

    def test_restore_prefix_drops_only_the_dependencies(self):
        key, prefix = ci_cargo_cache.cache_key("ci", "identity", "deps", self.ENV)
        self.assertTrue(key.startswith(prefix))
        self.assertTrue(prefix.startswith("cargo-v1-ci-ubuntu24-X64-"))
        other, other_prefix = ci_cargo_cache.cache_key(
            "ci", "identity", "other deps", self.ENV
        )
        self.assertEqual(other_prefix, prefix)
        self.assertNotEqual(other, key)

    def test_identity_changes_the_prefix(self):
        _, prefix = ci_cargo_cache.cache_key("ci", "rustc 1.90", "deps", self.ENV)
        _, other = ci_cargo_cache.cache_key("ci", "rustc 1.91", "deps", self.ENV)
        self.assertNotEqual(prefix, other)

    def test_profile_sections_keep_only_profile_tables(self):
        manifest = (
            '[package]\nname = "pumice"\n\n'
            "# Debug builds.\n[profile.dev]\ndebug = 1\n\n"
            '[profile.dev.package."*"]\ndebug = false\n\n'
            '[dependencies]\nserde = "1"\n\n'
            "[profile.release]\nlto = true\n"
        )
        self.assertEqual(
            ci_cargo_cache.profile_sections(manifest),
            '[profile.dev]\ndebug = 1\n[profile.dev.package."*"]\ndebug = false\n'
            "[profile.release]\nlto = true",
        )

    def test_profile_sections_ignore_comments_and_other_tables(self):
        base = '[package]\nversion = "0.3.0"\n[profile.dev]\ndebug = 1\n'
        same = '[package]\nversion = "0.4.0"\n[profile.dev]\n# why\n\ndebug = 1\n'
        other = '[package]\nversion = "0.3.0"\n[profile.dev]\ndebug = 2\n'
        sections = ci_cargo_cache.profile_sections
        self.assertEqual(sections(base), sections(same))
        self.assertNotEqual(sections(base), sections(other))

    def test_profile_sections_accept_spaced_and_quoted_headers(self):
        sections = ci_cargo_cache.profile_sections
        for header in ("[ profile.dev ]", '["profile".dev]', "['profile'.dev]"):
            with self.subTest(header=header):
                manifest = f'[package]\nname = "pumice"\n{header}\ndebug = 1\n[[bin]]\nname = "x"\n'
                self.assertEqual(sections(manifest), f"{header}\ndebug = 1")

    def test_identity_covers_the_repository_profiles(self):
        root = ci_cargo_cache.REPO_ROOT
        identity = ci_cargo_cache.cache_identity("ci", "debug", self.ENV, root)
        profiles = ci_cargo_cache.profile_sections(
            (root / "Cargo.toml").read_text(encoding="utf-8")
        )
        self.assertIn("[profile.dev]", profiles)
        self.assertIn(f"profiles={ci_cargo_cache.short_hash(profiles)}", identity)


class PruneTests(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.target = Path(tmp.name) / "target"
        touch(self.target / "CACHEDIR.TAG")
        touch(self.target / ".rustc_info.json")
        make_profile(self.target / "debug")
        make_profile(self.target / "x86_64-unknown-linux-musl" / "release")
        touch(self.target / "x86_64-unknown-linux-musl" / "CACHEDIR.TAG.not-a-profile")
        nested = self.target / "cpu-variants"
        touch(nested / "CACHEDIR.TAG")
        make_profile(nested / "release")
        touch(nested / "stage" / "pumice-transcribe")
        touch(nested / "cargo-build.json")
        touch(self.target / "tmp" / "test-scratch")

    def kept(self, profile: str) -> set:
        return {
            name
            for name in listing(self.target)
            if name.startswith(profile + "/")
        }

    def test_profiles_keep_only_dependencies(self):
        ci_cargo_cache.prune_target(self.target, WORKSPACE)
        for profile in ("debug", "x86_64-unknown-linux-musl/release", "cpu-variants/release"):
            self.assertEqual(
                self.kept(profile),
                {
                    f"{profile}/.fingerprint/opus-{DEP_HASH}/lib-opus",
                    f"{profile}/.fingerprint/transcribe-cpp-sys-{SYS_HASH}/run-build-script",
                    f"{profile}/build/transcribe-cpp-sys-{SYS_HASH}/output",
                    f"{profile}/build/transcribe-cpp-sys-{SYS_HASH}/out/lib/libtranscribe.so",
                    f"{profile}/build/transcribe-cpp-sys-{SYS_HASH}/out/build/CMakeCache.txt",
                    f"{profile}/deps/libopus-{DEP_HASH}.rlib",
                    f"{profile}/deps/opus-{DEP_HASH}.d",
                    f"{profile}/deps/transcribe.dll",
                },
                profile,
            )

    def test_target_directories_keep_their_markers_only(self):
        ci_cargo_cache.prune_target(self.target, WORKSPACE)
        top = {
            name
            for name in listing(self.target)
            if "/" not in name or name.startswith("cpu-variants/") and name.count("/") == 1
        }
        self.assertEqual(
            top,
            {"CACHEDIR.TAG", ".rustc_info.json", "cpu-variants/CACHEDIR.TAG"},
        )
        self.assertFalse((self.target / "tmp").exists())
        self.assertFalse((self.target / "x86_64-unknown-linux-musl" / "CACHEDIR.TAG.not-a-profile").exists())


if __name__ == "__main__":
    unittest.main()
